    { word: "customer", phonetic: "/ˈkʌstəmər/", def: "A person or organization that buys goods or services from a store or business.", defVn: "khách hàng, người mua hàng", pos: "noun", ex: ["The friendly shopkeeper greeted every customer with a smile.", "Customer satisfaction is our top priority."], exVn: ["Chủ cửa hàng thân thiện chào đón mọi khách hàng bằng nụ cười.", "Sự hài lòng của khách hàng là ưu tiên hàng đầu của chúng tôi."] },
    { word: "shopkeeper", phonetic: "/ˈʃɑːpkiːpər/", def: "An owner or manager of a small shop.", defVn: "chủ tiệm, người bán hàng", pos: "noun", ex: ["The helpful shopkeeper recommended fresh organic honey.", "Support local neighborhood shopkeepers."], exVn: ["Chủ tiệm nhiệt tình đã gợi ý mật ong hữu cơ tươi ngon.", "Hãy ủng hộ các chủ cửa hàng tạp hóa địa phương nhé."] },
    { word: "change", phonetic: "/tʃeɪndʒ/", def: "Coins or smaller banknotes given in exchange for a larger banknote.", defVn: "tiền lẻ thối lại, tiền thừa", pos: "noun", ex: ["Here is your coffee and three dollars in change.", "Keep the change as a tip, thank you!"], exVn: ["Cà phê của bạn đây và ba đô la tiền thừa nhé.", "Xin giữ lại tiền lẻ làm tiền tip, cảm ơn bạn!"] },
    { word: "expensive", phonetic: "/ɪkˈspensɪv/", def: "Costing a lot of money.", defVn: "đắt đỏ, giá cao", pos: "adj", ex: ["Dining at a Michelin-starred restaurant can be expensive.", "Designer luxury watches are very expensive."], exVn: ["Ăn tối tại nhà hàng gắn sao Michelin có thể rất đắt đỏ.", "Những chiếc đồng hồ hàng hiệu xa xỉ có giá rất cao."] },
    { word: "cheap", phonetic: "/tʃiːp/", def: "Costing little; inexpensive.", defVn: "rẻ, giá cả bình dân", pos: "adj", ex: ["Street food in Hanoi is both delicious and cheap.", "She found a cheap flight ticket online."], exVn: ["Ẩm thực đường phố Hà Nội vừa thơm ngon lại vừa rẻ.", "Cô ấy đã tìm được chiếc vé máy bay giá rẻ trực tuyến."] }
