    { word: "papaya", phonetic: "/pəˈpaɪə/", def: "An elongated tropical fruit with orange flesh and small black seeds.", defVn: "quả đu đủ", pos: "noun", ex: ["Sweet ripe papaya contains beneficial digestive enzymes.", "Green papaya is the main ingredient in traditional salads."], exVn: ["Đu đủ chín ngọt chứa nhiều men tiêu hóa có lợi.", "Đu đủ xanh là nguyên liệu chính trong món nộm truyền thống."] },
    { word: "dragon fruit", phonetic: "/ˈdræɡən fruːt/", def: "A tropical fruit with bright pink skin and sweet white or red flesh speckled with black seeds.", defVn: "quả thanh long (ruột trắng / ruột đỏ)", pos: "noun", ex: ["Red-fleshed dragon fruit has a vibrant magenta color.", "Dragon fruit is exported from Vietnam to many nations."], exVn: ["Thanh long ruột đỏ có màu đỏ tím rất rực rỡ.", "Thanh long được xuất khẩu từ Việt Nam sang nhiều quốc gia."] },
    { word: "durian", phonetic: "/ˈdʊriən/", def: "A large spiky tropical fruit with a strong distinctive odor and creamy custard-like flesh.", defVn: "quả sầu riêng (vua các loài quả)", pos: "noun", ex: ["Durian is famously known as the king of tropical fruits.", "The creamy golden flesh of durian has a rich aroma."], exVn: ["Sầu riêng nổi danh là vua của các loài hoa quả nhiệt đới.", "Múi sầu riêng vàng ươm béo ngậy tỏa hương thơm đậm đà."] },
    { word: "avocado", phonetic: "/ˌævəˈkɑːdoʊ/", def: "A pear-shaped fruit with a rough leathery skin, smooth oily edible flesh, and a large stone.", defVn: "quả bơ, trái bơ sáp", pos: "noun", ex: ["An avocado smoothie with condensed milk is rich and creamy.", "Spread mashed avocado on morning toast."], exVn: ["Sinh tố bơ sữa đặc béo ngậy và thơm ngon.", "Phết bơ dầm lên bánh mì nướng buổi sáng."] },
    { word: "bamboo", phonetic: "/ˌbæmˈbuː/", def: "A giant woody grass that grows chiefly in the tropics and is used for construction and crafts.", defVn: "cây tre, cây trúc", pos: "noun", ex: ["Green bamboo groves symbolize resilience in Vietnamese culture.", "Bamboo shoots are a delicious soup ingredient."], exVn: ["Những lũy tre xanh tượng trưng cho sự kiên cường trong văn hóa Việt.", "Măng tre là nguyên liệu nấu canh rất thơm ngon."] },
    { word: "lotus", phonetic: "/ˈloʊtəs/", def: "An aquatic plant with large pink or white flowers and round floating leaves; national flower.", defVn: "hoa sen (quốc hoa Việt Nam)", pos: "noun", ex: ["The pink lotus rises elegantly above the muddy pond.", "Lotus tea has a delicate and soothing fragrance."], exVn: ["Bông sen hồng vươn lên thanh cao trên mặt hồ bùn.", "Trà ướp hoa sen có hương thơm tao nhã và thanh tịnh."] },
    { word: "rose", phonetic: "/roʊz/", def: "A woody perennial flowering plant with prickles and fragrant flowers.", defVn: "hoa hồng (biểu tượng tình yêu)", pos: "noun", ex: ["He presented a bouquet of fragrant red roses to his mother.", "Dewdrops sparkled on the rose petals."], exVn: ["Anh ấy tặng mẹ một bó hoa hồng đỏ ngát hương.", "Những giọt sương mai lấp lánh trên từng cánh hoa hồng."] },
    { word: "sunflower", phonetic: "/ˈsʌnflaʊər/", def: "A tall plant with a very large golden-yellow flower head that turns towards the sun.", defVn: "hoa hướng dương (hướng về mặt trời)", pos: "noun", ex: ["A field of golden sunflowers swayed in the gentle wind.", "Sunflowers always track the warm morning sunlight."], exVn: ["Cánh đồng hoa hướng dương vàng rực đung đưa trong gió nhẹ.", "Hoa hướng dương luôn hướng theo ánh nắng ban mai ấm áp."] },
    { word: "root", phonetic: "/ruːt/", def: "The part of a plant which attaches it to the ground and conveys water and nutrients.", defVn: "rễ cây (hút nước và chất dinh dưỡng)", pos: "noun", ex: ["Deep tree roots anchor the tall tree during storms.", "Ginger is a flavorful underground root."], exVn: ["Bộ rễ cây ăn sâu giúp giữ vững thân cây trong giông bão.", "Gừng là một loại củ rễ dưới lòng đất rất thơm."] }
