  // Theme 30: Giải trí & Nghệ thuật (Entertainment & Arts)
  t_basic_entertainment_arts: [
    { word: "movie", phonetic: "/ˈmuːvi/", def: "A story or event recorded by a camera as a set of moving images.", defVn: "bộ phim điện ảnh", pos: "noun", ex: ["Let's watch an entertaining comedy movie together this weekend.", "The animated movie won an international film award."], exVn: ["Cuối tuần này chúng ta cùng xem một bộ phim hài giải trí nhé.", "Bộ phim hoạt hình đã đoạt giải thưởng điện ảnh quốc tế."] },
    { word: "music", phonetic: "/ˈmjuːzɪk/", def: "Vocal or instrumental sounds combined in such a way as to produce beauty of form, harmony, and expression.", defVn: "âm nhạc, giai điệu", pos: "noun", ex: ["Listening to gentle acoustic music helps you relax and study.", "Music connects people across different languages."], exVn: ["Lắng nghe âm nhạc acoustic nhẹ nhàng giúp bạn thư giãn và học tập.", "Âm nhạc kết nối con người vượt qua mọi rào cản ngôn ngữ."] },
    { word: "concert", phonetic: "/ˈkɑːnsərt/", def: "A musical performance given in public, typically by several performers or of several compositions.", defVn: "buổi hòa nhạc, buổi biểu diễn ca nhạc", pos: "noun", ex: ["Thousands of singing fans gathered at the live stadium concert.", "The symphony orchestra gave a mesmerizing classical concert."], exVn: ["Hàng ngàn người hâm mộ tụ họp tại buổi hòa nhạc trực tiếp ở sân vận động.", "Dàn nhạc giao hưởng đã mang đến buổi hòa nhạc cổ điển đầy mê hoặc."] },
    { word: "song", phonetic: "/sɔːŋ/", def: "A short poem or other set of words set to music or meant to be sung.", defVn: "bài hát, ca khúc", pos: "noun", ex: ["Sing along to your favorite English song to improve pronunciation.", "This folk song has a catchy and sweet melody."], exVn: ["Hát theo bài hát tiếng Anh yêu thích để nâng cao phát âm nhé.", "Bài hát dân ca này có giai điệu bắt tai và rất ngọt ngào."] },
    { word: "dance", phonetic: "/dæns/", def: "Move rhythmically to music, typically following a set sequence of steps.", defVn: "điệu nhảy, khiêu vũ", pos: "noun", ex: ["Traditional Vietnamese bamboo dance is lively and festive.", "Dancing to upbeat music burns calories and lifts your mood."], exVn: ["Điệu múa sạp tre truyền thống của Việt Nam rất sôi động và lễ hội.", "Nhảy theo nhạc sôi động giúp đốt cháy calo và nâng cao tinh thần."] },
    { word: "game", phonetic: "/ɡeɪm/", def: "A form of play or sport, especially a competitive one played according to rules.", defVn: "trò chơi, trò chơi điện tử / bàn cờ", pos: "noun", ex: ["Playing interactive vocabulary games makes English learning fun.", "They played a competitive board game on Saturday night."], exVn: ["Chơi các trò chơi từ vựng tương tác giúp việc học tiếng Anh thú vị hơn.", "Họ đã chơi trò chơi cờ bàn đầy kịch tính vào tối thứ Bảy."] },
    { word: "show", phonetic: "/ʃoʊ/", def: "A spectacle, display, or performance, typically in a theatre, on television, or in a circus.", defVn: "buổi trình diễn, chương trình biểu diễn", pos: "noun", ex: ["The traditional water puppet show in Hanoi is culturally unique.", "We watched an entertaining live magic show."], exVn: ["Chương trình múa rối nước truyền thống ở Hà Nội mang nét văn hóa độc đáo.", "Chúng tôi xem một buổi biểu diễn ảo thuật trực tiếp rất hấp dẫn."] },
    { word: "circus", phonetic: "/ˈsɜːrkəs/", def: "A travelling company of acrobats, clowns, and other entertainers which gives performances.", defVn: "gánh xiếc, rạp xiếc nghệ thuật", pos: "noun", ex: ["Acrobats performed breathtaking aerial stunts at the circus.", "Children laughed joyfully at the circus clowns."], exVn: ["Các nghệ sĩ xiếc biểu diễn những màn nhào lộn trên không ngoạn mục.", "Lũ trẻ cười giòn giã trước những chú hề rạp xiếc."] },
    { word: "magic", phonetic: "/ˈmædʒɪk/", def: "The power of apparently influencing events by using mysterious or supernatural forces; conjuring tricks.", defVn: "ảo thuật, phép màu kỳ diệu", pos: "noun", ex: ["The skilled magician pulled a white rabbit from his hat with magic.", "The fairy tale had a world filled with magic."], exVn: ["Nhà ảo thuật tài ba rút chú thỏ trắng từ chiếc mũ bằng ảo thuật.", "Câu chuyện cổ tích có một thế giới ngập tràn phép màu kỳ diệu."] },
    { word: "art", phonetic: "/ɑːrt/", def: "The expression or application of human creative skill and imagination.", defVn: "nghệ thuật (hội họa, điêu khắc)", pos: "noun", ex: ["Art allows us to express deep human emotions creatively.", "She studies traditional lacquer art in Hanoi."], exVn: ["Nghệ thuật cho phép chúng ta thể hiện cảm xúc sâu sắc một cách sáng tạo.", "Cô ấy học nghệ thuật tranh sơn mài truyền thống tại Hà Nội."] },
    { word: "gallery", phonetic: "/ˈɡæləri/", def: "A room or building for the display or sale of works of art.", defVn: "phòng triển lãm nghệ thuật, phòng tranh", pos: "noun", ex: ["The contemporary art gallery exhibited oil paintings by young artists.", "Admission to the city gallery is free on Fridays."], exVn: ["Phòng tranh đương đại trưng bày các tác phẩm sơn dầu của họa sĩ trẻ.", "Vé vào phòng triển lãm thành phố miễn phí vào các ngày thứ Sáu."] },
    { word: "actor", phonetic: "/ˈæktər/", def: "A person whose profession is acting on the stage, in movies, or on television.", defVn: "nam diễn viên điện ảnh / kịch", pos: "noun", ex: ["The talented actor delivered a powerful dramatic performance.", "He won the Best Actor award at the film festival."], exVn: ["Người nam diễn viên tài năng đã mang đến màn diễn xuất đầy nội lực.", "Anh ấy đoạt giải Nam diễn viên xuất sắc nhất tại liên hoan phim."] },
    { word: "actress", phonetic: "/ˈæktrəs/", def: "A female actor.", defVn: "nữ diễn viên điện ảnh / kịch", pos: "noun", ex: ["The famous actress starred in three international movies this year.", "She trained at the drama academy to become an actress."], exVn: ["Nữ diễn viên nổi tiếng đã đóng vai chính trong ba bộ phim quốc tế năm nay.", "Cô ấy theo học tại học viện kịch nghệ để trở thành diễn viên."] },
    { word: "festival", phonetic: "/ˈfestɪvl/", def: "A day or period of celebration, typically a religious or cultural commemoration.", defVn: "lễ hội văn hóa / âm nhạc", pos: "noun", ex: ["Hue Festival celebrates imperial culture with grand music and art.", "The international film festival takes place in autumn."], exVn: ["Festival Huế tôn vinh văn hóa cung đình bằng âm nhạc và nghệ thuật hoành tráng.", "Liên hoan phim quốc tế diễn ra vào mùa thu."] },
    { word: "sculpture", phonetic: "/ˈskʌlptʃər/", def: "The art of making two- or three-dimensional representative or abstract forms by carving stone or wood.", defVn: "tác phẩm điêu khắc, tượng nghệ thuật", pos: "noun", ex: ["The museum features ancient bronze and marble sculptures.", "The artist carved a graceful wooden sculpture."], exVn: ["Bảo tàng trưng bày các tác phẩm điêu khắc bằng đồng và đá cẩm thạch cổ.", "Người nghệ sĩ đã đẽo gọt một bức tượng gỗ đầy duyên dáng."] }
  ]
